import { useState, useEffect } from "react";
import { Link, useNavigate } from "react-router-dom";
import axios from "axios";

function History() {
  const [history, setHistory] = useState([]);
  const [loading, setLoading] = useState(true);
  const [user, setUser] = useState(null);
  const navigate = useNavigate();

  useEffect(() => {
    const stored = localStorage.getItem("user");
    if (!stored) {
      navigate("/login");
      return;
    }
    
    try {
      const userData = JSON.parse(stored);
      if (userData && userData.email) {
        setUser(userData);
        fetchHistory(userData.email);
      } else {
        localStorage.removeItem("user");
        navigate("/login");
      }
    } catch (e) {
      localStorage.removeItem("user");
      navigate("/login");
    }
  }, [navigate]);

  const fetchHistory = async (email) => {
    try {
      const res = await axios.get(`http://127.0.0.1:5000/history/${email}`);
      setHistory(res.data.history || []);
    } catch (err) {
      console.error("Error fetching history:", err);
    }
    setLoading(false);
  };

  const clearHistory = async () => {
    if (!window.confirm("Are you sure you want to clear all history?")) return;
    
    try {
      await axios.delete(`http://127.0.0.1:5000/history/clear/${user.email}`);
      setHistory([]);
      alert("History cleared successfully");
    } catch (err) {
      alert("Error clearing history");
    }
  };

  const getUrgencyColor = (urgency) => {
    switch(urgency) {
      case "High": return "#c62828";
      case "Medium": return "#ef6c00";
      default: return "#2e7d32";
    }
  };

  const getUrgencyBg = (urgency) => {
    switch(urgency) {
      case "High": return "#ffebee";
      case "Medium": return "#fff3e0";
      default: return "#e8f5e9";
    }
  };

  if (loading) {
    return (
      <div style={{
        minHeight: "100vh",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        background: "#f5f5f5"
      }}>
        <p>Loading history...</p>
      </div>
    );
  }

  return (
    <div style={{
      minHeight: "100vh",
      background: "#f5f5f5",
      fontFamily: "Arial, sans-serif"
    }}>
      {/* Header */}
      <div style={{
        background: "linear-gradient(135deg, #667eea 0%, #764ba2 100%)",
        padding: "20px 40px",
        display: "flex",
        justifyContent: "space-between",
        alignItems: "center"
      }}>
        <h2 style={{color: "white", margin: 0}}>📋 My Health History</h2>
        <div style={{display: "flex", gap: "10px"}}>
          <Link to="/health">
            <button style={{
              padding: "10px 20px",
              background: "white",
              color: "#667eea",
              border: "none",
              borderRadius: "5px",
              cursor: "pointer",
              fontWeight: "bold"
            }}>New Check</button>
          </Link>
          <Link to="/">
            <button style={{
              padding: "10px 20px",
              background: "transparent",
              color: "white",
              border: "2px solid white",
              borderRadius: "5px",
              cursor: "pointer"
            }}>Home</button>
          </Link>
        </div>
      </div>

      {/* Content */}
      <div style={{padding: "30px", maxWidth: "900px", margin: "0 auto"}}>
        {user && (
          <div style={{
            background: "white",
            padding: "20px",
            borderRadius: "10px",
            marginBottom: "20px",
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center"
          }}>
            <div>
              <h3 style={{margin: "0 0 5px"}}>{user.name}</h3>
              <p style={{margin: 0, color: "#666"}}>{user.email}</p>
            </div>
            <div style={{textAlign: "right"}}>
              <p style={{margin: 0, color: "#666"}}>Total Checks: <strong>{history.length}</strong></p>
            </div>
          </div>
        )}

        {history.length === 0 ? (
          <div style={{
            background: "white",
            padding: "60px 40px",
            borderRadius: "10px",
            textAlign: "center"
          }}>
            <div style={{fontSize: "60px", marginBottom: "20px"}}>📭</div>
            <h3 style={{color: "#333", marginBottom: "10px"}}>No History Yet</h3>
            <p style={{color: "#666", marginBottom: "20px"}}>
              You haven't performed any symptom checks yet. Start by checking your symptoms!
            </p>
            <Link to="/health">
              <button style={{
                padding: "14px 30px",
                background: "linear-gradient(135deg, #667eea 0%, #764ba2 100%)",
                color: "white",
                border: "none",
                borderRadius: "8px",
                fontSize: "16px",
                cursor: "pointer",
                fontWeight: "bold"
              }}>
                Check Symptoms Now
              </button>
            </Link>
          </div>
        ) : (
          <>
            <div style={{display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "20px"}}>
              <h3 style={{margin: 0}}>Recent Checks</h3>
              <button 
                onClick={clearHistory}
                style={{
                  padding: "8px 16px",
                  background: "#f5f5f5",
                  color: "#666",
                  border: "1px solid #ddd",
                  borderRadius: "5px",
                  cursor: "pointer",
                  fontSize: "14px"
                }}
              >
                Clear All History
              </button>
            </div>

            {history.map((entry, idx) => (
              <div key={idx} style={{
                background: "white",
                padding: "20px",
                borderRadius: "10px",
                marginBottom: "15px",
                boxShadow: "0 2px 5px rgba(0,0,0,0.05)"
              }}>
                <div style={{display: "flex", justifyContent: "space-between", marginBottom: "15px"}}>
                  <span style={{color: "#999", fontSize: "14px"}}>
                    📅 {new Date(entry.date).toLocaleDateString('en-US', {
                      year: 'numeric',
                      month: 'long',
                      day: 'numeric',
                      hour: '2-digit',
                      minute: '2-digit'
                    })}
                  </span>
                  <span style={{
                    background: getUrgencyBg(entry.urgency),
                    color: getUrgencyColor(entry.urgency),
                    padding: "4px 12px",
                    borderRadius: "15px",
                    fontSize: "12px",
                    fontWeight: "bold"
                  }}>
                    {entry.urgency} Urgency
                  </span>
                </div>

                <div style={{marginBottom: "15px"}}>
                  <p style={{margin: "0 0 5px", color: "#666", fontSize: "14px"}}>Symptoms Described:</p>
                  <p style={{margin: 0, fontStyle: "italic", color: "#333"}}>"{entry.symptoms_text}"</p>
                </div>

                <div style={{
                  background: "#f8f9fa",
                  padding: "15px",
                  borderRadius: "8px",
                  display: "flex",
                  justifyContent: "space-between",
                  alignItems: "center"
                }}>
                  <div>
                    <p style={{margin: "0 0 5px", fontSize: "14px", color: "#666"}}>Predicted Condition:</p>
                    <h3 style={{margin: 0, color: "#e74c3c"}}>{entry.disease}</h3>
                  </div>
                  <div style={{textAlign: "right"}}>
                    <p style={{margin: 0, fontSize: "24px", fontWeight: "bold", color: "#667eea"}}>
                      {entry.confidence}%
                    </p>
                    <p style={{margin: 0, fontSize: "12px", color: "#999"}}>Confidence</p>
                  </div>
                </div>

                {entry.symptoms_detected && entry.symptoms_detected.length > 0 && (
                  <div style={{marginTop: "10px"}}>
                    <p style={{margin: "0 0 5px", fontSize: "12px", color: "#999"}}>
                      Detected Symptoms: {entry.symptoms_detected.map(s => s.replace(/_/g, " ")).join(", ")}
                    </p>
                  </div>
                )}

                {entry.possible_conditions && entry.possible_conditions.length > 0 && (
                  <div style={{marginTop: "5px"}}>
                    <p style={{margin: 0, fontSize: "12px", color: "#999"}}>
                      Also consider: {entry.possible_conditions.join(", ")}
                    </p>
                  </div>
                )}
              </div>
            ))}
          </>
        )}
      </div>
    </div>
  );
}

export default History;
